//! Password-manager "do not record" markers.
//!
//! Password managers tag what they put on the clipboard. If a tag is present we
//! drop the clip entirely: not stored, not even for 120 s.
//!
//!   Windows: ExcludeClipboardContentFromMonitorProcessing, "Clipboard Viewer Ignore",
//!            CanIncludeInClipboardHistory = 0            (KeePass, Bitwarden, 1Password…)
//!   macOS:   org.nspasteboard.ConcealedType / TransientType / AutoGeneratedType,
//!            com.agilebits.onepassword                   (nspasteboard.org convention)
//!   Linux:   x-kde-passwordManagerHint target on X11      (KeePassXC, KDE)
//!            Wayland: not checkable from a background app -> secret detection only.

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Marker {
    Clean,
    Excluded(&'static str),
}

// ---------------------------------------------------------------- Windows
#[cfg(windows)]
pub fn check() -> Marker {
    use clipboard_win::{raw, register_format, Clipboard};

    for (name, why) in [
        ("ExcludeClipboardContentFromMonitorProcessing", "ExcludeClipboardContentFromMonitorProcessing"),
        ("Clipboard Viewer Ignore", "Clipboard Viewer Ignore"),
    ] {
        if let Some(fmt) = register_format(name) {
            if raw::is_format_avail(fmt.get()) {
                return Marker::Excluded(why);
            }
        }
    }

    // CanIncludeInClipboardHistory: DWORD, 0 = "do not keep in history"
    if let Some(fmt) = register_format("CanIncludeInClipboardHistory") {
        if raw::is_format_avail(fmt.get()) {
            if let Ok(_guard) = Clipboard::new_attempts(10) {
                let mut buf = [0u8; 4];
                if raw::get(fmt.get(), &mut buf).is_ok() && u32::from_le_bytes(buf) == 0 {
                    return Marker::Excluded("CanIncludeInClipboardHistory=0");
                }
            }
        }
    }
    Marker::Clean
}

// ---------------------------------------------------------------- macOS
#[cfg(target_os = "macos")]
pub fn check() -> Marker {
    use objc2::{msg_send, rc::Retained, ClassType};
    use objc2_app_kit::NSPasteboard;

    const CONCEALED: [&str; 4] = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
    ];

    objc2::rc::autoreleasepool(|_| {
        // generalPasteboard can be NULL when running as a daemon; don't panic on that.
        let pb: Option<Retained<NSPasteboard>> =
            unsafe { msg_send![NSPasteboard::class(), generalPasteboard] };
        let Some(pb) = pb else { return Marker::Clean };
        let Some(types) = pb.types() else { return Marker::Clean };
        for t in types.iter() {
            let t = t.to_string();
            if let Some(hit) = CONCEALED.iter().find(|c| **c == t) {
                return Marker::Excluded(hit);
            }
        }
        Marker::Clean
    })
}

// ---------------------------------------------------------------- Linux / BSD (X11)
#[cfg(all(unix, not(target_os = "macos")))]
pub fn check() -> Marker {
    // Wayland-only sessions have no DISPLAY; XWayland sessions do and work here.
    if std::env::var_os("DISPLAY").is_none() {
        return Marker::Clean;
    }
    x11_targets()
        .map(|targets| {
            if targets.iter().any(|t| t == "x-kde-passwordManagerHint") {
                Marker::Excluded("x-kde-passwordManagerHint")
            } else {
                Marker::Clean
            }
        })
        .unwrap_or(Marker::Clean)
}

/// Asks the current CLIPBOARD owner for its TARGETS list (the formats it offers).
#[cfg(all(unix, not(target_os = "macos")))]
fn x11_targets() -> Result<Vec<String>, Box<dyn std::error::Error>> {
    use std::time::{Duration, Instant};
    use x11rb::connection::Connection;
    use x11rb::protocol::xproto::{AtomEnum, ConnectionExt, CreateWindowAux, WindowClass};
    use x11rb::protocol::Event;

    let (conn, screen_num) = x11rb::connect(None)?;
    let root = conn.setup().roots[screen_num].root;
    let win = conn.generate_id()?;
    conn.create_window(
        x11rb::COPY_DEPTH_FROM_PARENT, win, root, 0, 0, 1, 1, 0,
        WindowClass::INPUT_ONLY, x11rb::NONE, &CreateWindowAux::new(),
    )?;

    let atom = |name: &[u8]| -> Result<u32, Box<dyn std::error::Error>> {
        Ok(conn.intern_atom(false, name)?.reply()?.atom)
    };
    let clipboard = atom(b"CLIPBOARD")?;
    let targets = atom(b"TARGETS")?;
    let prop = atom(b"CLIPGUARD_TARGETS")?;

    conn.convert_selection(win, clipboard, targets, prop, x11rb::CURRENT_TIME)?;
    conn.flush()?;

    let deadline = Instant::now() + Duration::from_millis(300);
    let got = loop {
        match conn.poll_for_event()? {
            Some(Event::SelectionNotify(e)) => break e.property != x11rb::NONE,
            Some(_) => continue,
            None if Instant::now() > deadline => break false,
            None => std::thread::sleep(Duration::from_millis(5)),
        }
    };

    let mut names = Vec::new();
    if got {
        let reply = conn.get_property(true, win, prop, AtomEnum::ATOM, 0, 1024)?.reply()?;
        if let Some(atoms) = reply.value32() {
            for a in atoms {
                let n = conn.get_atom_name(a)?.reply()?.name;
                names.push(String::from_utf8_lossy(&n).into_owned());
            }
        }
    }
    let _ = conn.destroy_window(win);
    let _ = conn.flush();
    Ok(names)
}
